messages.content:
Tool response:
Tool: split_expense
Description: Split Expense
Parameters:
    {
      "type": "object",
      "properties": {
        "expense_id": {
          "type": "integer",
          "description": "ID of the expense to split",
          "title": "Expense Id"
        },
        "__body__": {
          "type": "array",
          "items": {
            "properties": {
              "category_id": {
                "type": "integer",
                "title": "Category Id"
              },
              "amount": {
                "type": "number",
                "title": "Amount"
              },
              "note": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Note"
              }
            },
            "type": "object",
            "required": [
              "category_id",
              "amount"
            ],
            "title": "SplitItem"
          },
          "description": "List of splits with category_id, amount, and optional note",
          "title": "Splits"
        }
      },
      "required": [
        "expense_id",
        "__body__"
      ]
    }
